{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Thalidomide, which shares the glutarimide and N-aryl imide/lactam core with the query, has an absolute oral bioavailability of 80–100% in fasting healthy volunteers, directly supporting a high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Aminoglutethimide, a glutarimide bearing a primary aromatic amine like the query, has an oral bioavailability of ≈100%, indicating that the aniline moiety does not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Nevirapine, a fused aromatic lactam with an absolute oral bioavailability of 93%, supports that this heterocyclic lactam class is well absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence, thalidomide, shows absolute oral bioavailability of 80–100% in fasting humans. The query shares the glutarimide and N-aryl lactam/imide core; the added primary aromatic amine is also present in aminoglutethimide, which has ≈100% F. Although the query's low logP and possible first-pass metabolism introduce uncertainty, the weight of experimental evidence supports F ≥20%.",
  "evidence_gaps": [
    "No direct bioavailability data exist for the exact query molecule.",
    "The metabolic stability and first-pass effect of the primary aromatic amine are not directly characterized.",
    "The impact of replacing a phthalimide carbonyl with a methylene on permeability and efflux is not directly tested.",
    "No human PK data under fasted conditions are available for the query itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

